import{icon}from"/assets/icons.e3d1ddbc39d8.js";export function copyChord(){const nav=typeof navigator==="undefined"?{}:navigator;const platform=nav.userAgentData&&nav.userAgentData.platform||nav.platform||nav.userAgent||"";return/mac|iphone|ipad|ios/i.test(platform)?"Cmd+C":"Ctrl+C"}export function writeClipboard(text,host=document.body){const legacy=()=>new Promise(((resolve,reject)=>{const back=document.activeElement;const ta=document.createElement("textarea");ta.value=text;ta.setAttribute("readonly","");ta.setAttribute("aria-hidden","true");ta.tabIndex=-1;ta.style.cssText="position:fixed;top:0;left:0;width:1px;height:1px;opacity:0";host.appendChild(ta);ta.select();let done=false;try{done=document.execCommand("copy")}catch(_){done=false}ta.remove();if(back&&back.focus)back.focus();if(done)resolve();else reject(new Error("the clipboard refused the copy"))}));if(navigator.clipboard&&window.isSecureContext)return navigator.clipboard.writeText(text).catch(legacy);return legacy()}export function copyFace(word="Copy"){const glyph=document.createElement("span");glyph.className="cp-ic";glyph.setAttribute("aria-hidden","true");const check=icon("check","b");check.querySelector("path").setAttribute("pathLength","1");glyph.append(icon("copy","a"),check);if(word==null)return[glyph];const label=document.createElement("span");label.className="cp-lbl";const was=Object.assign(document.createElement("span"),{className:"a",textContent:word});const now=Object.assign(document.createElement("span"),{className:"b",textContent:"Copied"});label.append(was,now);return[glyph,label]}const answered=new WeakMap;export function flashCopied(btn,ok=true){clearTimeout(answered.get(btn));const said=btn.querySelector(":scope > .cp-lbl > .b");if(said)said.textContent=ok?"Copied":"Copy failed";btn.classList.toggle("is-copied",ok);btn.classList.toggle("is-failed",!ok);answered.set(btn,setTimeout((()=>btn.classList.remove("is-copied","is-failed")),2e3))}export function copyLine(node,{text:text=()=>node.textContent.trim(),name:name="",host:host=document.body,at:at=node,copied:copied=null,failed:failed=null}={}){node.classList.add("cp-line");node.title="Copy";const label=()=>node.setAttribute("aria-label",`Copy ${name||text()}`);label();if(!name)new MutationObserver(label).observe(node,{childList:true,characterData:true,subtree:true});const said=document.createElement("span");said.className="cp-said";said.setAttribute("aria-live","polite");at.after(said);let back=null;const answer=ok=>{clearTimeout(back);said.textContent="";said.classList.toggle("bad",!ok);said.classList.add("on");node.classList.toggle("is-copied",ok);setTimeout((()=>{said.textContent=ok?"Copied":"Copy failed"}),30);back=setTimeout((()=>{said.classList.remove("on");node.classList.remove("is-copied")}),2e3)};const run=async()=>{try{await writeClipboard(text(),host);answer(true);if(copied)copied()}catch(_){const range=document.createRange();range.selectNodeContents(node);getSelection().removeAllRanges();getSelection().addRange(range);answer(false);if(failed)failed()}};node.addEventListener("click",run);if(node.tagName!=="BUTTON"){node.setAttribute("role","button");node.tabIndex=0;node.addEventListener("keydown",(e=>{if(e.key!=="Enter"&&e.key!==" ")return;e.preventDefault();run()}))}return run}